/* 统一列表标题栏组件：只增强组件插槽，不拼装业务页面。 */
(()=>{
 const page=document.body.dataset.page;if(!EAM_LIST_TOOLS_JSON.pages[page])return;
 const header=document.querySelector('[data-component="list-toolbar"]');if(!header)return;
 const icon=EamUiComponents.toolIcon;
 for(const button of header.querySelectorAll('[data-list-tool]'))icon(button,button.dataset.listTool,button.dataset.label);
 const filter=header.querySelector('[data-filter-toggle],#open-advanced-filter');if(filter)icon(filter,'filter','高级筛选');
 const tools=header.querySelector('.list-panel-tools');for(const wrapper of tools.querySelectorAll(':scope>.actions')){for(const child of [...wrapper.children])tools.insertBefore(child,wrapper);wrapper.remove();}for(const key of ['import','export','refresh','columns']){const button=tools.querySelector('[data-list-tool='+key+']');if(button)tools.insertBefore(button,tools.querySelector(':scope>button:not([data-list-tool])'));}const table=document.querySelector('main table');let busy=false;
 const dialog=document.getElementById('list-tools-dialog'),content=document.getElementById('list-tools-body'),status=document.getElementById('list-tools-status'),confirm=document.getElementById('list-tools-confirm');let importData=null,valid=false,importKey='';
 document.getElementById('list-tools-close').onclick=()=>dialog.close();
 function open(title){document.getElementById('list-tools-title').textContent=title;content.replaceChildren();status.textContent='';confirm.hidden=true;confirm.disabled=false;dialog.showModal();}
 const prefsKey='eam-columns-'+page;let hiddenColumns=JSON.parse(sessionStorage.getItem(prefsKey)||'[]');
 function applyColumns(){if(!table)return;EamUiComponents.columnVisibility(table,hiddenColumns);}
 if(table){new MutationObserver(applyColumns).observe(table,{childList:true,subtree:true});applyColumns();}
 const field=(text)=>{const label=document.createElement('label');label.className='field';label.textContent=text;return label;};
 header.addEventListener('click',async event=>{const button=event.target.closest('[data-list-tool]');if(!button)return;event.stopPropagation();const action=button.dataset.listTool;
 if(action==='columns'){open('列设置');const help=document.createElement('p');help.textContent='首列与操作列固定保留；设置在当前会话内保存。';content.append(help);for(let i=0;i<table.tHead.rows[0].cells.length;i++){const label=field(table.tHead.rows[0].cells[i].textContent),input=document.createElement('input');input.type='checkbox';input.checked=!hiddenColumns.includes(i);input.disabled=i===0||i===table.tHead.rows[0].cells.length-1;input.onchange=()=>{hiddenColumns=input.checked?hiddenColumns.filter(x=>x!==i):[...hiddenColumns,i];sessionStorage.setItem(prefsKey,JSON.stringify(hiddenColumns));applyColumns();};label.prepend(input);content.append(label);}return;}
 if(action==='import'){open('导入 · 校验与预览');importData=null;valid=false;importKey=crypto.randomUUID();const note=document.createElement('p');note.textContent='JSON批次：schema=1、page为当前页面、rows为数据数组。提交后暂存待字段映射审核，不直接生成业务记录或任务。';content.append(note);const label=field('选择JSON文件（最大2MB，最多500条）'),file=document.createElement('input');file.type='file';file.accept='.json,application/json';file.className='form-control';label.append(file);content.append(label);const reasonLabel=field('导入原因 *'),reason=document.createElement('textarea');reason.className='form-control';reasonLabel.append(reason);content.append(reasonLabel);const preview=document.createElement('pre');preview.className='list-import-preview';content.append(preview);confirm.hidden=false;confirm.disabled=true;confirm.textContent='提交待审核批次';file.onchange=async()=>{valid=false;confirm.disabled=true;status.textContent='校验中…';try{if(!file.files[0]||file.files[0].size>2*1024*1024)throw Error('请选择2MB以内JSON文件');importData=JSON.parse(await file.files[0].text());const result=await EamListToolsApi.request('POST','/list-tools/import/validate',{page,data:importData});preview.textContent=JSON.stringify(result.rows.slice(0,3),null,2);status.textContent=result.errors.length?result.errors.map(x=>'第'+x.row+'条：'+x.message).join('；'):'校验通过，共'+result.count+'条（预览前3条）';valid=!result.errors.length;confirm.disabled=!valid;}catch(e){status.textContent=e.message;}};confirm.onclick=async()=>{if(!valid||busy)return;busy=true;confirm.disabled=true;try{const result=await EamListToolsApi.request('POST','/list-tools/import',{page,data:importData,reason:reason.value,idempotencyKey:importKey});status.textContent='已暂存'+result.count+'条，批次'+result.id+'；待字段映射及业务审核。';valid=false;}catch(e){status.textContent=e.message;confirm.disabled=false;}finally{busy=false;}};return;}
 if(busy)return;busy=true;button.disabled=true;try{if(action==='export'){const result=await EamListToolsApi.request('GET','/list-tools/export',{page});const url=URL.createObjectURL(new Blob([JSON.stringify(result,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=page+'-导出.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);Eam.message('已导出权限范围内'+result.rows.length+'条（JSON，不限当前分页）');}else if(action==='refresh'){await EamListToolsApi.request('GET','/list-tools/export',{page});if(typeof button.onclick==='function')await button.onclick(event);else location.reload();}}catch(e){Eam.message(e.message);}finally{busy=false;button.disabled=false;}},true);
 const importButton=tools.querySelector('[data-list-tool=import]');if(importButton){importButton.disabled=!Eam.can(['engineer','supervisor']);if(importButton.disabled)importButton.title='当前角色没有导入权限';}
})();
